algorithms.pseudocode:
function AlienShadow(L):
    seen <- empty set
    result <- empty list
    for i in L:
        if i not in seen:
            seen <- seen union {i}
            result.append(i)
    return result

Time: O(n) expected with hash set
Space: O(n)

function TestDedupIdentity(semirings, test_lists, test_points):
    for S in semirings:
        holds <- true
        for L in test_lists:
            shadow <- AlienShadow(L)
            for x in test_points:
                if S.eval(x, L) != S.eval(x, shadow):
                    holds <- false
                    report counterexample (S, L, x)
                    break
        report (S.name, holds)

Time: O(|semirings| * |test_lists| * |test_points| * max_list_len)

